// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 am, uint256 collectAmt, uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= am);
        try c.Collect(collectAmt) {} catch { return; }
        bool reverted;
        try c.SetMinSum(dummy) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(uint256 am, uint256 collectAmt, uint256 dummy) public {
        _run(am, collectAmt, dummy);
    }

    receive() external payable {}
}
